// Read only: only .work generated by prepare-modern-passenger.mjs.
import assert from 'node:assert/strict'
import {readFileSync,writeFileSync,mkdirSync,realpathSync,readdirSync,statSync} from 'node:fs'
import {resolve,relative,join,dirname} from 'node:path'
import {createHash} from 'node:crypto'
import {fileURLToPath} from 'node:url'
const expected={"packId":"8b27746f727f258c8180c0d3a1c917c62f14a94c083025767eef4ec7682dba40","manifestSha256":"367c0104a8a5de7f11bdf2c965eb91a73e1cf21b5a3809f78f53e7170b7cdebb","mapExtractHash":"c50dd021ab11518b230c191bc9fa85f683c9b82810f605476532c16172f55238","catalog":{"version":1,"extractHash":"c50dd021ab11518b230c191bc9fa85f683c9b82810f605476532c16172f55238"}}
const sha=b=>createHash('sha256').update(b).digest('hex')
const root=realpathSync(process.argv[2]),temp=realpathSync(process.env.RUNNER_TEMP)
assert.ok(root.startsWith(temp+'/apois-modern-passenger-')&&root.endsWith('/workspace'),'only isolated rehearsal workspace')
const config=join(root,'src/components/navigation/pilot-config.ts')
const before=readFileSync(config,'utf8')
assert.ok(before.includes('PILOT_INSTALLED:boolean=false')&&before.includes('NEW_SELECTION_ENABLED:boolean=false'),'pilot must remain disabled')
const pack=process.argv[3]
if(pack){
 const source=realpathSync(pack),manifest=readFileSync(join(source,'manifest.json'))
 assert.equal(sha(manifest),expected.manifestSha256,'manifest pin')
 const m=JSON.parse(manifest);assert.equal(m.pack_id,expected.packId);assert.equal(m.extract_sha256,expected.mapExtractHash)
 assert.ok(Array.isArray(m.files)&&m.files.length<=36)
 let bytes=0;const entries=[]
 for(const f of m.files){
  assert.ok(typeof f.path==='string'&&/^(vale\.pmtiles|style\.json|OSM-NOTICE\.txt|LICENSE-Open-Sans\.txt|glyphs\/Open Sans Regular\/\d+-\d+\.pbf)$/.test(f.path))
  const path=realpathSync(join(source,f.path));assert.ok(path.startsWith(source+'/'))
  const data=readFileSync(path);assert.equal(data.length,f.bytes);assert.equal(sha(data),f.sha256);bytes+=data.length
  entries.push([f.path,data])
 }
 assert.ok(bytes<=16*1024*1024)
 const target=join(root,'public/apois-regional');mkdirSync(target,{recursive:true})
 for(const [path,data] of entries){const dest=join(target,path);mkdirSync(dirname(dest),{recursive:true});writeFileSync(dest,data,{flag:'wx'})}
 writeFileSync(join(target,'manifest.json'),manifest,{flag:'wx'})
 console.log('APOIS_PRIVATE_PACK_STAGED',JSON.stringify({bytes,packId:m.pack_id,extractHash:m.extract_sha256}))
}
writeFileSync(config,"// Generated exclusively in disposable laboratory workspace; flags stay false.\nimport {supabase} from \"@/integrations/supabase/client\";\nimport {prepareApprovedPilotMap,type PilotMapPolicy} from \"../../../experimental/apois-navigation/ui/approved-map-provider.mjs\";\nexport const PILOT_INSTALLED:boolean=false;\nexport const NEW_SELECTION_ENABLED:boolean=false;\nexport type PilotMap={map:unknown;catalog:unknown;dispose:()=>void};\nexport const APPROVED_POLICY:PilotMapPolicy={\n  \"packId\": \"8b27746f727f258c8180c0d3a1c917c62f14a94c083025767eef4ec7682dba40\",\n  \"manifestSha256\": \"367c0104a8a5de7f11bdf2c965eb91a73e1cf21b5a3809f78f53e7170b7cdebb\",\n  \"mapExtractHash\": \"c50dd021ab11518b230c191bc9fa85f683c9b82810f605476532c16172f55238\",\n  \"catalog\": {\n    \"version\": 1,\n    \"extractHash\": \"c50dd021ab11518b230c191bc9fa85f683c9b82810f605476532c16172f55238\"\n  }\n};\nexport async function preparePilotMap(root:HTMLElement,account:string,signal:AbortSignal):Promise<PilotMap|null>{\n if(!PILOT_INSTALLED||!NEW_SELECTION_ENABLED||signal.aborted)return null;\n try{\n  const [lib,pm]=await Promise.all([import(\"maplibre-gl\"),import(\"pmtiles\"),import(\"maplibre-gl/dist/maplibre-gl.css\")]);\n  if(signal.aborted)return null;\n  return await prepareApprovedPilotMap(root,{\n   enabled:true,account,auth:supabase.auth,\n   invoke:(name:string,options:Parameters<typeof supabase.functions.invoke>[1])=>supabase.functions.invoke(name,options),\n   maplibre:lib.default,PMTiles:pm.PMTiles,base:new URL(\"./apois-regional/\",document.baseURI).href,\n   origin:location.origin,policy:APPROVED_POLICY,signal\n  });\n }catch{return null;}\n}\n")
console.log('APOIS_PRIVATE_MAP_PROVIDER_STAGED',JSON.stringify({installed:false,newSelectionEnabled:false,packStaged:!!pack}))
